    N(A7, "x3-3a-envir", "Vocabulaire : environnement et santé", ["Les sujets du BFEM abordent souvent l'environnement et la santé.", "Il faut connaître le vocabulaire de base."],
      ["pollution, waste, plastic bags, to recycle, to protect, trees, desert, drought, flood.", "health, disease, malaria, mosquito net, vaccine, hospital, doctor, nurse.", "to wash your hands, clean water, balanced diet.", "Connecteurs : because, so, but, however, firstly, finally."],
      ("Un conseil écrit", ["We should stop throwing plastic bags in the street.", "Firstly, they pollute ; secondly, they kill animals."]),
      [("« sécheresse » :", "drought", "flood", "desert", "waste", "Manque de pluie."), ("« moustiquaire » :", "mosquito net", "mosquito bite", "fishing net", "net ball", "Paludisme."), ("« recycler » :", "to recycle", "to rebuild", "to return", "to repeat", "Environnement."), ("« inondation » :", "flood", "drought", "storm", "wind", "Trop d'eau.")]),
    N(A7, "x3-3a-letter", "Écrire une lettre ou un e-mail", ["Le BFEM demande souvent une courte production écrite : lettre, e-mail ou paragraphe.", "Il faut respecter une forme et des formules."],
      ["Début : Dear Awa, / Dear Sir,", "Corps : présentation, raison de la lettre, détails.", "Fin : Best wishes, / Love, (ami) ; Yours faithfully, (formel).", "Signature ; phrases simples, temps corrects, connecteurs."],
      ("E-mail à un correspondant", ["Dear John, I'm writing to tell you about my school…", "I hope to hear from you soon. Best wishes, Moussa."]),
      [("Début formel :", "Dear Sir,", "Hi guys,", "Love,", "Bye,", "Lettre officielle."), ("Fin amicale :", "Best wishes,", "Yours faithfully,", "Dear John,", "To whom it may concern,", "Ami."), ("« J'espère avoir de tes nouvelles » :", "I hope to hear from you soon.", "I hope to listen you.", "I wait your news.", "I hear you soon.", "Formule."), ("« Je t'écris pour… » :", "I'm writing to…", "I write for…", "I am write to…", "I writing to…", "Formule.")]),
